using System;using System.IO;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Diagnostics;
class MalformedReply {static int Main(){var json=new JavaScriptSerializer();var clock=Stopwatch.StartNew();string line=Console.ReadLine();if(line==null)return 2;var request=json.Deserialize<Dictionary<string,object>>(line);string mode=Path.GetFileName((string)request["root"]);if(mode=="helper-exit")return 2;var reply=new Dictionary<string,object>{{"version",1},{"requestId",request["requestId"]},{"session",request["session"]},{"generation",request["generation"]},{"clockMs",clock.ElapsedMilliseconds},{"status","ACK"}};switch(mode){case "deadline-clock":reply["clockMs"]=request["deadlineMs"];break;case "wrong-version":reply["version"]=2;break;case "wrong-session":reply["session"]="00000000-0000-0000-0000-000000000000";break;case "wrong-generation":reply["generation"]=2;break;case "wrong-request":reply["requestId"]=2;break;case "negative-clock":reply["clockMs"]=-1;break;case "fractional-clock":reply["clockMs"]=0.5;break;case "unknown-field":reply["extra"]=true;break;case "invalid-utf8":using(var output=Console.OpenStandardOutput()){output.WriteByte(255);output.WriteByte(10);output.Flush();}Console.ReadLine();return 0;}string body=json.Serialize(reply);if(mode=="noncanonical-body")body+=" ";if(mode=="oversized-frame")body=new string((char)32,131073);if(mode=="double-cr")body+="\r\r";Console.Write(body+"\n");Console.ReadLine();return 0;}}
